// ExchangePairingResponse Identity-shaped enrollment result.
//
// The rotating secret is a refresh token in an identity refresh family and
// the access token is DPoP-bound to the enrolled device key. The former
// deviceGrantId/deviceGrant/deviceGrantExpiresAt/accessSessionId quartet is
// gone because the underlying concepts are gone, not because it was
// renamed — see internal/control/http/v3/pairing/types.go.
//
// The token fields are camelCase here and snake_case in
// DeviceGrantResponse, which spells them the RFC 6749 way. This is the
// deviating side of that boundary, kept deliberately: it is a pairing
// result that happens to carry tokens rather than an OAuth token endpoint,
// and every client already decodes it in this spelling.
type ExchangePairingResponse struct {
	AccessToken string              `json:"accessToken"`
	DeviceId    string              `json:"deviceId"`
	Endpoints   []PublishedEndpoint `json:"endpoints"`

	// ExpiresIn Access-token lifetime in seconds, counted from the moment of this response.
	//
	// Example: 900
	ExpiresIn     int32  `json:"expiresIn"`
	PairingId     string `json:"pairingId"`
	PolicyVersion string `json:"policyVersion"`

	// RefreshToken Rotates on every refresh. Presenting a superseded value is treated as replay and revokes the entire refresh family.
	RefreshToken string `json:"refreshToken"`

	// Scope Space-delimited scope string granted to the enrolled device.
	Scope string `json:"scope"`

	// TokenType Always "DPoP"; the access token is sender-constrained to the enrolled device key.
	//
	// Example: DPoP
	TokenType string `json:"tokenType"`
}

